var e={R1:JSON.parse(`{"title":"التوصيل والتخاطب","heading":"وصّل القارئ وتخاطب مع شريحته","goal":"برنامج ثابت خاص بها (rfid-lab-r1؛ لكل مختبر RFID برنامجه الثابت) مع مشغّل من تأليفنا في kit/lib/rfid-kit: لا مكتبة RFID، فكل بايت أمامك مكشوف. ثمانية أسلاك تضع RC522 على ناقل SPI الثاني في ESP32-S3، فلا يشاركه مع الشاشة. أول حوار يكون مع الشريحة نفسها لا مع بطاقة: سجل الإصدار فيها، والاختبار الذاتي من ورقة البيانات، و3,200 بايت تمر عبر FIFO وتعود.","goalLine":"أثبت أن ESP32 وشريحة القارئ يتخاطبان بثبات عبر SPI قبل إدخال أي بطاقة. أبعد البطاقة والوسم عن القارئ الآن.","goalCheck":["يعرض المراقب <code>VersionReg 0x92: MFRC522 v2.0</code> (أو 0x91، أو قيمة شريحة مقلّدة)، وليس 0x00 ولا 0xFF.","ينتهي الأمر <code>selftest</code> بالرسالة <code>self-test passed: 64/64 bytes match</code> مع شريحة NXP أصلية (91h/92h)، أو <code>self-test consistent: 2 runs, same 64 bytes</code> مع شريحة مقلّدة مثل FM17522 (88h/B2h).","يعرض الأمر <code>loopback</code> الرسالة <code>0 of 3200 bytes wrong</code>.","في عرض <b>الشريحة</b>: يتوهج المربع بلون أخضر مزرق وتواصل عدّادات الناقل الارتفاع."],"learn":["بايت عنوان SPI","السجلات","FIFO","الاختبار الذاتي في ورقة البيانات","ناقلا SPI","قراءة عطل في الناقل"],"pins":{"0":{"role":"VCC"},"1":{"role":"RC 3.3V"},"2":{"role":"BLK"},"3":{"role":"RES"},"4":{"role":"DC"},"5":{"role":"CS"},"6":{"role":"SDA"},"7":{"role":"SCL"},"8":{"role":"GND"},"9":{"role":"RC SDA"},"10":{"role":"RC SCK"},"11":{"role":"MOSI"},"12":{"role":"MISO"},"13":{"role":"RC RST"},"14":{"role":"IRQ"},"15":{"role":"RC GND"},"16":{"role":"BTN"},"17":{"role":"BOOT"}},"wiring":{"title":"توصيل RC522 (8 أسلاك جديدة، وتبقى الشاشة كما هي)","head":["طرف RC522","ESP32-S3","الدور"],"rows":[["SDA","GPIO 15","اختيار الشريحة (NSS) في وضع SPI، وليس بيانات I2C"],["SCK","GPIO 16","ساعة SPI، من ESP32"],["MOSI","GPIO 17","بيانات من ESP32 إلى الشريحة"],["MISO","GPIO 18","بيانات من الشريحة إلى ESP32"],["IRQ","GPIO 13","اختياري: تقول الشريحة «انتهيت»"],["GND","GND","الطرف العلوي في الصف الأيمن"],["RST","GPIO 14","إعادة ضبط؛ المستوى المنخفض = إيقاف التشغيل"],["3.3V","3V3","طرف 3V3 الثاني. لا تستخدم 5V أبدًا"]]},"commands":{"0":{"does":"يبني البرنامج الثابت للمختبر R1 ويرفعه إلى اللوحة (بلا تنزيلات جديدة: يستخدم مكتبات الشاشة التي لديك أصلًا).","see":"<code>Hard resetting via RTS pin…</code>. تبدأ الشاشة على عرض <b>البطاقة</b>: حلقات، و“Hold a card or tag”.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يفتح المراقب التسلسلي (Serial Monitor). فتحه يعيد تشغيل اللوحة، فترى أسطر البدء.","see":"<code>RC522 on SPI3: SS 15 SCK 16 MOSI 17 MISO 18 RST 14 IRQ 13 · 4 MHz</code> ثم <code>VersionReg 0x92: MFRC522 v2.0</code> وقائمة الأوامر.","fix":"<code>0x00</code>: الشريحة بلا طاقة أو MISO عالق على المستوى المنخفض: افحص 3.3V وGND وRST. <code>0xFF</code>: لا أحد يقود MISO: افحص MISO (18) وSDA (15)."},"2":{"does":"يقرأ VersionReg (37h) مرة أخرى: عملية النقل ذات البايتين الموضحة أعلاه، مباشرةً.","see":"السطر نفسه كما عند البدء (<code>0x92</code>، أو مثلًا <code>0xB2: FM17522 (clone)</code>). شغّله عدة مرات، ومرة أخرى بعد تحريك البطاقة: يجب ألا يتغير أبدًا.","fix":"إذا تغيّر، أو صار 00h/FFh بعد أن لمست القارئ فهذا يعني سلكًا مرتخيًا. اضغط مشبك RC522 جيدًا أو لحمه، ثم نفّذ <code>reset</code>."},"3":{"does":"يرسل نبضة على سلك RST (إعادة ضبط كاملة للشريحة)، ويهيئها من جديد ويقرأ VersionReg. كما يفحص البرنامج الثابت VersionReg بنفسه كل 2 s ويفعل ذلك تلقائيًا عندما تصمت الشريحة.","see":"<code>hard reset: VersionReg 0x92</code> (أو قيمة شريحتك المقلّدة). إذا كانت الشريحة قد صمتت: <code>chip back after a hard reset</code> = كانت معلّقة؛ <code>still 0x00 after a reset</code> = المشكلة في سلك.","fix":"ما زال 00h/FFh: افصل الطاقة، واضغط أطراف المشبك جيدًا (أو لحمها)، وافحص 3.3V وGND وMISO (18) وSDA (15)."},"4":{"does":"الاختبار الذاتي الرقمي في ورقة البيانات (القسم 16.1.1): يعيد ضبط الشريحة ويجعلها تحسب تسلسلًا ثابتًا من 64 بايت. تُقارَن شريحة NXP الأصلية (91h/92h) بجدول ورقة البيانات. أما المقلّدة فلا جدول لها، فيُجرى الاختبار مرتين وتُقارَن النتيجتان. يتوقف الاستطلاع أثناء التشغيل، فيمكن أن تبقى البطاقة في مكانها.","see":"4 صفوف من 16 بايت بلا علامات <code>!</code>، ثم <code>self-test passed: 64/64 bytes match</code> (NXP) أو <code>self-test consistent: 2 runs, same 64 bytes</code> (مقلّدة). يعرض عرض الشريحة <b>passed</b> أو <b>consistent</b>.","fix":"<code>self-test skipped: chip silent (0x00)</code> = الشريحة لم تكن تردّ قبل بدء الاختبار أصلًا: سلك، راجع <code>reset</code>. علامات <code>!</code> = بايتات مختلفة: أعد تثبيت SCK/MOSI/MISO وشغّل مرة أخرى. <code>doesn't run the self-test</code> = بعض الشرائح المقلّدة لا تملكه ببساطة؛ عندها يكون loopback هو الاختبار المعتمد."},"5":{"does":"يكتب أنماطًا من 64 بايت في FIFO الخاصة بالشريحة ويقرؤها مرة أخرى، 50 مرة: 3,200 بايت في كل اتجاه.","see":"<code>FIFO loopback: 0 of 3200 bytes wrong at 4 MHz</code> بلون أخضر مزرق في أسفل يمين الشاشة.","fix":"أي أخطاء عند 4 MHz = اتصال سيئ في SCK أو MOSI أو MISO، أو أسلاك أطول بكثير من 20 cm."},"6":{"does":"يطبع 15 سجلًا مع بتاتها ومعنى كل منها.","see":"<code>VersionReg 92h</code>، <code>TxControlReg 83h</code> (الهوائي يعمل)، <code>RFCfgReg 40h</code> (كسب 33 dB)، <code>TPrescalerReg A9h</code> + <code>TReloadReg 03 E8</code> (مؤقّت 25 ms: 1,000 نبضة، مدة كل منها 25 µs).","fix":"TxControlReg 80h = الهوائي متوقف: أُعيد ضبط الشريحة دون إعدادنا. افصل اللوحة ثم وصّلها من جديد."},"7":{"does":"نظرة اختيارية على مختبر الحافة: يشغّل الناقل عند 20 MHz، ضعف المعدّل المقرر للشريحة، ثم يعيده إلى الافتراضي.","see":"ربما بضعة بايتات خاطئة عند 20 MHz، وربما لا شيء: يعتمد على أسلاكك. تتحول ساعة SPI في عرض الشريحة إلى العنبري فوق 10.","fix":"أنهِ دائمًا بالأمر <code>spi 4</code>. يقيس مختبر الحافة R6 هذا قياسًا صحيحًا."}},"panels":{"0":{"title":"قراءة سجل واحد، بتًّا بتًّا","intro":"كل أمر في هذا الدرس مبني من عمليات نقل كهذه. هذا ما يعرضه محلل منطقي على أسلاك SPI الأربعة بينما يقرأ ESP32 سجلًا واحدًا: 16 نبضة ساعة، وبايتان. يخرج البايت الأول على MOSI ويحدد <b>أي</b> سجل و<b>قراءة أم كتابة</b>؛ وخلال البايت الثاني تجيب الشريحة على MISO. الأمر <code>chip</code> يفعل ذلك تمامًا مع VersionReg. استخدم ◀ ▶ للتنقل بتًّا بتًّا، أو اختر سجلًا آخر، أو اختر عطلًا لترى إلى ماذا يحوّل السلكُ المرتخي الجواب: هكذا ستقرأ 00h أو FFh في مراقبك."},"1":{"title":"ما تعرضه الشاشة","intro":"لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته."}},"steps":["افصل USB. أبقِ الشاشة موصولة كما في الدرس 03. أضف RC522 بـ 8 أسلاك توصيل أنثى-ذكر كما في الجدول: SDA وSCK وMOSI وMISO تذهب إلى 15 و16 و17 و18، جنبًا إلى جنب بالترتيب نفسه الموجود على الوحدة.","تحقق مرتين: طرف 3.3V في الوحدة يذهب إلى <b>3V3</b>، وليس 5V أبدًا. يعمل MFRC522 على 2.5–3.6 V وأطرافه لا تتحمل 5 V.","ارفع البرنامج إلى اللوحة، ثم افتح المراقب (أول أمرين أعلاه). <b>نقطة التحقق 1:</b> ‏VersionReg 0x92 (أو 0x91، أو قيمة شريحة مقلّدة).","اكتب <code>selftest</code>. <b>نقطة التحقق 2:</b> “passed” (شريحة NXP) أو “consistent” (شريحة مقلّدة).","اكتب <code>loopback</code>، ثم <code>regs</code>. <b>نقطة التحقق 3:</b> صفر بايت خاطئ، وقيم السجلات كما في الجدول.","انتقل إلى عرض <b>الشريحة</b> وقارنه بقسم «ما تعرضه الشاشة»: مربع أخضر مزرق، passed، 4 MHz، وعدّادات الناقل تتصاعد. هذا هو الهدف. ضع البطاقة على القارئ لثانية كمعاينة للدرس R2: يومض LED الموجود على اللوحة بالأخضر الساطع ويبقى أخضر ما دامت البطاقة موضوعة."],"note":"يخبرك LED الـ RGB الموجود على اللوحة بما يراه القارئ: وميض أخضر ساطع عند كل قراءة بطاقة، وأخضر ثابت ما دامت بطاقة على القارئ، وأحمر إذا توقفت شريحة القارئ عن الرد (سلك)، ومطفأ فيما عدا ذلك. تأتي كثير من لوحات RC522 بمشبك غير ملحوم: الأطراف المضغوطة تفقد الاتصال، فالحمه أو اضغطه بقوة. IRQ اختياري: بدونه يستطلع البرنامج الثابت الشريحة، ويعرض عرض الشريحة “polling” (يقارن R6 بين الحالتين). موضع البطاقة لا يغيّر أيًّا من نتائج R1. لكن التعامل معها قرب القارئ هو اللحظة التي تفقد فيها أطراف المشبك الاتصال: إذا صار VersionReg يعرض 00h/FFh بعد ذلك، فسيلاحظ البرنامج الثابت خلال 2 s، ويجرّب إعادة ضبط كاملة، ويخبرك هل كان تعليقًا أم سلكًا."}`),R2:{title:`أيقِظ بطاقة`,heading:`المجال، وأول تحية`,goal:`يولّد هوائي القارئ مجالًا مغناطيسيًا بتردد 13.56 MHz. البطاقة بلا بطارية: يلتقط ملفها طاقة هذا المجال، فتستيقظ شريحتها وتجيب بتحميل المجال بإيقاع يستطيع القارئ سماعه. أولًا بالثلاثي الأبعاد، ثم إطارًا إطارًا، ثم فعليًا في المتنصّت (sniffer).`,goalLine:`شاهد بطاقة تستيقظ وتجيب، واقرأ هويتها، واعرف مدى قارئك.`,goalCheck:[`يعرض عرض البطاقة UID بطاقتك، و“MIFARE Classic 1K”، وATQA 00 04 وSAK 08.`,`يسرد عرض التتبع إطارات الاستيقاظ: WUPA وATQA وANTICOLL وUID + BCC وSELECT وSAK وHLTA.`,`تعرف تقريبًا عند أي ارتفاع يبدأ معدل القراءة بالانخفاض (مداك).`],learn:[`المجال القريب 13.56 MHz`,`الاقتران الحثي`,`توقفات ASK بنسبة 100 %`,`التعديل بالحمل`,`REQA · WUPA · ATQA`,`مهمة استطلاع`,`التنصّت على الإطارات`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت الخاص بالمختبر R2: كل ما في R1، إضافةً إلى عرض التتبع وأمري poll وtrace. يسرد <code>help</code> أوامر هذا المختبر بالضبط.`,see:`<code>rfid-lab-r2: reader task started</code>، ثم قائمة أوامر هذا المختبر وعروضه.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`نقرة واحدة على الزر أو BOOT تنتقل إلى العرض التالي؛ والنقاط في الأعلى تبيّن العرض الحالي.`,see:`حلقات حول الهوائي و“Hold a card or tag flat on the reader”، مع عدد النقرات حتى الآن.`,fix:``},2:{does:`تستطلع مهمة القارئ نحو 12 مرة في الثانية؛ أول استطلاع يجد البطاقة يوقظها ويقرأ UID الخاص بها ثم يوقفها.`,see:`يومض LED الموجود على اللوحة بالأخضر الساطع، ثم يبقى أخضر ما دامت البطاقة موضوعة. يعرض عرض البطاقة UID والنوع وATQA/SAK ومعدل قراءة يمتلئ حتى 100 %. ويطبع المراقب <code>card 9C:4F:… · MIFARE Classic 1K · ATQA 0004 SAK 08</code> والإطارات.`,fix:`لا شيء؟ شغّل الأمر <code>chip</code> من R1 مرة أخرى؛ ثم جرّب وضع البطاقة مسطحة في منتصف الهوائي.`},3:{does:`يضعف المجال كلما ارتفعت البطاقة؛ وتبدأ عمليات الاستطلاع بالإخفاق.`,see:`يتحول معدل القراءة إلى العنبري، ثم المرجاني. بعد 3 إخفاقات متتالية (~0.3 s) يعرض المراقب <code>card removed</code>.`,fix:``},4:{does:`المتنصّت (sniffer): إطارات آخر عملية إيقاظ، مع الأزمنة بوحدة ms.`,see:`<code>&gt; 52 WUPA</code>، <code>&lt; 04 00 ATQA</code>، <code>&gt; 93 20 ANTICOLL CL1</code>، <code>&lt; UID + BCC</code>، <code>&gt; SELECT CL1</code>، <code>&lt; SAK</code>، <code>&gt; HLTA</code>.`,fix:`“Sniffer off”: اكتب <code>trace on</code>.`},5:{does:`المتنصّت يعمل افتراضيًا ويطبع إطارات كل بطاقة جديدة في المراقب. إيقافه يُسكت المراقب وعرض التتبع.`,see:`<code>sniffer off</code> / <code>sniffer on</code> في أسفل اليمين.`,fix:``},6:{does:`كسب المستقبِل 18 dB (0)، 48 dB (7)، والافتراضي 33 dB (4). أمسك البطاقة عند حافة مداك لكل قيمة.`,see:`يتغير معدل القراءة عند الارتفاع نفسه مع الكسب، لكن إلى حد معين فقط: في البعيد لا تملك البطاقة طاقة مهما كان الكسب.`,fix:`أنهِ بالأمر <code>gain 4</code>.`},7:{does:`يوقف استطلاع البطاقات مؤقتًا ويستأنفه.`,see:`يعرض عرض البطاقة “polling paused”؛ تُتجاهل البطاقات الجديدة حتى <code>poll on</code>.`,fix:``}},panels:{0:{title:`المجال بالثلاثي الأبعاد`,intro:`نموذج لقارئك وبطاقتك: اسحب لتدويره، وحرّك البطاقة صعودًا وهبوطًا، وغيّر الكسب، واضغط Send WUPA لتشاهد عملية إيقاظ واحدة. يوضح الرسم تحته سبب انتهاء المدى حيث ينتهي.`},1:{title:`تابع عملية إيقاظ واحدة خطوة بخطوة`,intro:`ما يحدث في أول ميلي ثانية بعد وصول بطاقة، من كتابات SPI في ESP32 إلى جواب البطاقة. تظهر الإطارات نفسها في المتنصّت لديك.`},2:{title:`ما تعرضه الشاشة`,intro:`لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته.`}},steps:[`التوصيل نفسه كما في R1. ارفع <code>rfid-lab-r2</code> إلى اللوحة (الأمر أعلاه)، ثم انتقل إلى عرض <b>البطاقة</b>.`,`ضع البطاقة البيضاء مسطحة على القارئ. <b>نقطة التحقق:</b> يومض LED بالأخضر الساطع ويبقى أخضر؛ UID، وMIFARE Classic 1K، ومعدل القراءة 100 %.`,`انتقل إلى عرض <b>التتبع</b> وابحث عن الإطارات السبعة؛ وقارنها بمخطط الخطوات أعلاه.`,`ارفع البطاقة ببطء ولاحظ الارتفاع الذي ينخفض عنده معدل القراءة: هذا مداك.`,`كرّر عند حافة المدى مع <code>gain 0</code> و<code>gain 7</code>، ثم <code>gain 4</code>. وقارن بتوقع النموذج ثلاثي الأبعاد.`,`جرّب سلسلة المفاتيح (الوسم): UID خاص به، ومن النوع نفسه.`],note:`يستطلع القارئ نحو 12 مرة في الثانية في مهمته الخاصة على النواة 0، فلا تنتظر الشاشة أبدًا. تُعدّ البطاقة مزالة بعد 3 استطلاعات فائتة متتالية فقط (~0.3 s)، فلا يجعلها استطلاع ضعيف واحد عند حافة المدى تومض. النموذج ثلاثي الأبعاد مبسّط عمدًا: قِس مداك الحقيقي في R6.`},R3:{title:`من هناك`,heading:`بطاقتان معًا: مكافحة التصادم`,goal:`ضع البطاقة والوسم على القارئ معًا. تجيب كلتاهما في اللحظة نفسها، بتًّا بتًّا، وحيث يختلف UID بينهما يسمع القارئ تصادمًا. تنزل مكافحة التصادم عبر البتات كشجرة ثنائية: اختر فرعًا، واسأل مرة أخرى بهذه البادئة، واختر البطاقة المتبقية، وأوقفها، وكرّر حتى لا يجيب أحد.`,goalLine:`اعثر على البطاقتين معًا، وحدّد البت الذي تصادم عنده UID الخاص بهما.`,goalCheck:[`يسرد <code>inventory</code> بطاقتين مع UID كل منهما.`,`يسمّي بت التصادم، ويقع الشرح التفصيلي أعلاه على البت نفسه مع UID الخاصين بك.`],learn:[`تصادمات البتات`,`النزول في الشجرة الثنائية`,`NVB`,`BCC`,`مستويات التعاقب (cascade)`,`SAK`,`HALT · WUPA`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت الخاص بالمختبر R3: كل ما في R2، إضافةً إلى inventory (والنقر المزدوج في عرض البطاقة يشغّله). يسرد <code>help</code> أوامر هذا المختبر بالضبط.`,see:`<code>rfid-lab-r3: reader task started</code>، ثم قائمة أوامر هذا المختبر وعروضه.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`تستيقظ البطاقتان على WUPA نفسه. يحل الاستطلاع التصادم ويختار إحداهما.`,see:`يعرض عرض البطاقة UID واحدًا (هو نفسه دائمًا) وسطرًا عنبريًا: <code>collision at bit 23</code> (سيختلف البت عندك).`,fix:`وُجدت بطاقة واحدة فقط؟ قرّبهما أكثر من التداخل: يجب أن تقعا معًا داخل حلقة الهوائي.`},2:{does:`يوقف المجال 10 ms لتعيد كل بطاقة التشغيل، ثم REQA ← اختيار ← إيقاف، مرارًا حتى لا يجيب أحد.`,see:`<code>#1 9C:4F:6A:0D … collision at level 1 bit 23 -&gt; chose 1</code>، <code>#2 9C:4F:2A:1B …</code>، ثم <code>inventory: 2 cards in the field</code>.`,fix:`<code>select failed (collision)</code>: حرّك البطاقتين قليلًا وشغّل الأمر مرة أخرى.`},3:{does:`المسار نفسه، ولا شيء يحتاج إلى حل.`,see:`<code>1 card</code> بلا سطر تصادم، ثم <code>0 cards</code>.`,fix:``}},panels:{0:{title:`مكافحة التصادم: نزول عبر البتات`,intro:`الصفان هما بتات UID لبطاقتين، بترتيب انتقالها (البت الأقل أهمية في البايت 0 أولًا). تقدّم خطوة بخطوة: حيث تختلف البتات يسمع القارئ تصادمًا، فيختار 1، ولا تواصل الإجابة إلا البطاقة المطابقة. اكتب UID الخاصين بك من المراقب.`},1:{title:`ما تعرضه الشاشة`,intro:`لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته.`}},steps:[`ارفع <code>rfid-lab-r3</code> إلى اللوحة بالأمر أعلاه (التوصيل نفسه كما في R1). يعرض <code>help</code> أوامر هذا المختبر.`,`ضع البطاقة والوسم على القارئ معًا، متداخلتين.`,`راقب عرض البطاقة: UID واحد، وبت التصادم بالعنبري.`,`اكتب <code>inventory</code> (أو انقر مرتين في عرض البطاقة). <b>نقطة التحقق:</b> بطاقتان، وبت التصادم.`,`اكتب UID الاثنين في الشرح التفصيلي أعلاه وتقدّم إلى الخطوة 2: يقع التصادم على البت نفسه.`,`اترك الاثنتين على القارئ: يعرض عرض البطاقة البطاقة نفسها دائمًا. يختار المسار 1 دائمًا عند التصادم، فتفوز البطاقة نفسها في كل مرة.`],note:`تنتقل البتات من الأقل أهمية أولًا، فـ“bit 23” هو البت 6 من البايت الثالث في UID. مشغّلنا مُختبَر مع بطاقتين معًا: ومع ثلاث أو أكثر يصعب الوثوق بموضع التصادم الذي تعطيه الشريحة بعد الفرع الأول. تحتاج UID من 7 بايتات إلى مستويي تعاقب؛ ويبدأ الجزء الأول بـ 88h، وسم التعاقب.`},R4:{title:`داخل البطاقة`,heading:`افتح ذاكرة البطاقة`,goal:`تحمل MIFARE Classic 1K ‏1,024 بايت: 16 قطاعًا × 4 كتل × 16 بايت. لكل قطاع قفله الخاص، وهو المقطع الختامي (trailer): مفتاحان إضافةً إلى بتات وصول تحدد من يحق له قراءة كل كتلة أو الكتابة فيها. افتح كل قطاع في بطاقتك بمفتاح المصنع واستخرج محتواه.`,goalLine:`استخرج ذاكرة بطاقتك كاملة، واشرح الكتلة 0 وبايتًا بايتًا في المقطع الختامي لأحد القطاعات.`,goalCheck:[`ينتهي <code>dump</code> بالرسالة <code>dump: 16 sectors read</code>، ويصبح عرض الذاكرة ملونًا كله (بلا قطاعات «مغلقة» رمادية).`,`في المخرجات يمكنك أن تشير إلى UID في الكتلة 0 وإلى <code>FF 07 80 69</code> في المقطع الختامي، ويشرح المفسّر أعلاه ما يسمح به FF 07 80.`],learn:[`القطاعات والكتل`,`المقاطع الختامية للقطاعات`,`بتات الوصول (مخزّنة مرتين)`,`المصادقة بثلاث مراحل`,`إطارات مشفّرة`,`كتلة الشركة المصنّعة`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت الخاص بالمختبر R4: كل ما في R3، إضافةً إلى عرض الذاكرة وأمري dump وread. يسرد <code>help</code> أوامر هذا المختبر بالضبط.`,see:`<code>rfid-lab-r4: reader task started</code>، ثم قائمة أوامر هذا المختبر وعروضه.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`لكل قطاع من القطاعات الـ16: صادِق بمفتاح المصنع A، واقرأ كتله الأربع، وفكّ ترميز المقطع الختامي. يستغرق نحو 1.5 s؛ أبقِ البطاقة ثابتة.`,see:`64 سطرًا (الكتلة، 16 بايت، ASCII، المعنى)، ثم <code>dump: 16 sectors read</code>. عرض الذاكرة: الكتلة 0 عنبرية، والكتل الفارغة داكنة، والمقاطع الختامية مرجانية.`,fix:`القطاعات الرمادية «المغلقة»: مفتاحها ليس مفتاح المصنع (بطاقة أعدّها أحدهم): يتركها المختبر وشأنها. “no card”: تحركت البطاقة؛ شغّل الأمر مرة أخرى.`},2:{does:`يصادق على القطاع 0 ويقرأ الكتلة 0 فقط.`,see:`UID (4 بايتات)، وBCC، ثم 08 04 00 (SAK، ATQA)، ثم بايتات الشركة المصنّعة.`,fix:``},3:{does:`الأمر نفسه للكتلة 1، مع عرض المتنصّت للإطارات.`,see:`<code>AUTH key A</code> معلَّمة بأنها تمت داخل الشريحة، ثم <code>READ</code> و16 بايت، وكلاهما “[encrypted on air]”.`,fix:``}},panels:{0:{title:`ذاكرة البطاقة بالثلاثي الأبعاد`,intro:`كل خزانة قطاع، وكل لوح كتلة، واللوح العلوي هو المقطع الختامي بقفله. انقر على قطاع ثم Authenticate: عندها فقط يمكن قراءة كتله.`},1:{title:`مفسّر بتات الوصول`,intro:`البايتات 6–8 من كل مقطع ختامي تحدد من يحق له فعل ماذا في ذلك القطاع. علّم البتات أو اكتب البايتات الثلاثة من مخرجاتك.`},2:{title:`صادِق ثم اقرأ، خطوة بخطوة`,intro:`ما يفعله <code>read 4</code> واحد على الناقل وفي الهواء.`},3:{title:`ما تعرضه الشاشة`,intro:`لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته.`}},steps:[`ارفع <code>rfid-lab-r4</code> إلى اللوحة بالأمر أعلاه (التوصيل نفسه كما في R1). يعرض <code>help</code> أوامر هذا المختبر.`,`أمسك البطاقة البيضاء على القارئ وأبقها ثابتة. اكتب <code>dump</code> (أو انقر مرتين في عرض الذاكرة). <b>نقطة التحقق:</b> قراءة 16 قطاعًا.`,`في المخرجات، اقرأ الكتلة 0: UID وBCC وSAK وATQA وبايتات الشركة المصنّعة.`,`ابحث عن مقطع ختامي (الكتل 3 و7 و11…): يظهر المفتاح A كـ 00 (لا تكشفه البطاقة أبدًا)، ثم <code>FF 07 80 69</code>، ثم المفتاح B.`,`اكتب <code>FF 07 80</code> في مفسّر بتات الوصول أعلاه: كتل البيانات 000، والمقطع الختامي 001.`,`نفّذ <code>read 1</code> وعرض التتبع مفتوح: ترى AUTH وREAD المشفّرة.`],note:`تجري المصادقة داخل MFRC522 (أمره MFAuthent): يسلّم ESP32 المفتاح ولا يرى المصافحة أبدًا، ولا يدخل المفتاح في التتبع أبدًا. لا يستخدم البرنامج الثابت إلا مفتاح المصنع، على بطاقات تملكها، ولا يكتب الكتلة 0 ولا مقطعًا ختاميًا أبدًا: المقطع الختامي ببتات وصول معطوبة يقفل قطاعه إلى الأبد.`},R5:{title:`اكتب وعُدّ`,heading:`اكتب ملصقًا، واحتفظ بعدّاد`,goal:`اكتب 16 بايت من عندك في كتلة بيانات ثم اقرأها مرة أخرى. بعد ذلك استخدم الحساب المدمج في MIFARE: كتلة القيمة تخزّن عددًا ثلاث مرات (مرة منها معكوسة) وتجري البطاقة نفسها الجمع أو الطرح، ثم تثبّت النتيجة في خطوة واحدة. وتحتفظ كتلة نسخ احتياطي بالقيمة السابقة.`,goalLine:`اكتب نصًا على بطاقتك، واحتفظ عليها بعدّاد رصيد تحدّثه البطاقة نفسها.`,goalCheck:[`يعرض <code>write 4 hello bench</code> العبارة “written and read back”.`,`بعد <code>credits init 50</code> و<code>credits use 3</code>، يعرض عرض الرصيد 47 مع نسخة احتياطية 50.`,`يعرض <code>dump</code> الكتلة 4 كبيانات والكتلتين 8 و9 ككتلتي قيمة.`],learn:[`كتابة الكتل · ACK / NAK`,`فحوص القراءة بعد الكتابة`,`تنسيق كتلة القيمة`,`INCREMENT · DECREMENT · TRANSFER`,`كتل النسخ الاحتياطي`,`حواجز الأمان`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت الخاص بالمختبر R5: كل ما في R4، إضافةً إلى عرض الرصيد وأمري write وcredits. يسرد <code>help</code> أوامر هذا المختبر بالضبط.`,see:`<code>rfid-lab-r5: reader task started</code>، ثم قائمة أوامر هذا المختبر وعروضه.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`يفتح القطاع 1، ويتحقق من أن بتات وصوله تسمح بالكتابة بالمفتاح A، ويكتب 16 بايت (النص مُتمَّم بأصفار)، ثم يقرؤها مرة أخرى.`,see:`بايتات الكتلة 4، <code>|hello bench.....|</code> و<code>written and read back</code>.`,fix:`<code>READ BACK DIFFERS</code>: تحركت البطاقة أثناء الكتابة؛ شغّل الأمر مرة أخرى.`},2:{does:`يحاول الكتابة في مقطع ختامي.`,see:`يُرفض قبل إرسال أي شيء: <code>not writable here (block 0 and trailers are off limits)</code>.`,fix:``},3:{does:`يكتب 50 ككتلة قيمة في الكتلة 8 والقيمة نفسها في النسخة الاحتياطية، الكتلة 9.`,see:`عرض الرصيد: 50، ونسخة احتياطية 50، وكومة عملات.`,fix:``},4:{does:`ينسخ القيمة إلى النسخة الاحتياطية، ثم تطرح البطاقة (أو تجمع) وتثبّت النتيجة بـ TRANSFER.`,see:`47، ونسخة احتياطية 50؛ ثم 57، ونسخة احتياطية 47.`,fix:`<code>no credits on this card yet</code>: شغّل credits init أولًا.`},5:{does:`يتحقق البرنامج الثابت من الرصيد أولًا.`,see:`<code>only 57 credits, can't use 999</code>: لا يُرسل شيء إلى البطاقة.`,fix:``},6:{does:`يقرأ الكتلتين 8 و9 ويفك ترميزهما.`,see:`القيمة الحالية والنسخة الاحتياطية.`,fix:``}},panels:{0:{title:`كتلة قيمة، بايتًا بايتًا`,intro:`كيف تخزّن البطاقة عددًا بحيث تستطيع التحقق منه بنفسها. غيّر القيمة وشاهد أي البايتات تتحرك.`},1:{title:`credits use 3، خطوة بخطوة`,intro:`أوامر البطاقة الأربعة وراء <code>credits use 3</code> واحد.`},2:{title:`ما تعرضه الشاشة`,intro:`لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته.`}},steps:[`ارفع <code>rfid-lab-r5</code> إلى اللوحة بالأمر أعلاه (التوصيل نفسه كما في R1). يعرض <code>help</code> أوامر هذا المختبر.`,`البطاقة على القارئ. <code>write 4 hello bench</code>. <b>نقطة التحقق:</b> written and read back.`,`<code>write 3 test</code>: يُرفض، فهو مقطع ختامي. وكذلك الكتلة 0.`,`<code>credits init 50</code>، ثم <code>credits use 3</code>. <b>نقطة التحقق:</b> 47، ونسخة احتياطية 50.`,`<code>credits add 10</code>: 57، ونسخة احتياطية 47. تقدّم عبر المخطط أعلاه لترى أوامر البطاقة الأربعة.`,`نفّذ <code>dump</code> مرة أخرى: الكتلة 4 بيانات، والكتلتان 8 و9 كتلتا قيمة.`],note:`الرصيد على MIFARE Classic لعبة للتعلّم وليس مالًا: يستطيع أي شخص يملك المفتاح إعادة كتابة الكتلة. تستخدم أنظمة الدفع والمواصلات بطاقات بتشفير حديث (مثل MIFARE DESFire) وتتحقق من كل عملية على خادم.`},R6:{title:`مختبر الحدود`,heading:`اعثر على الحدود على طاولتك أنت`,goal:`سبع تجارب تدفع كل منها إعدادًا واحدًا حتى ينكسر شيء: ساعة SPI، وكسب المستقبِل مقابل المسافة، وسرعة جواب البطاقة، والزمن الذي تستغرقه كل خطوة، والاستطلاع مقابل سلك IRQ، ووحدة CRC في الشريحة مقابل ESP32، ومئات القراءات المتتالية. ترسم كل تجربة مخططًا على الشاشة وتطبع جدولًا يمكنك لصقه في الأسفل.`,goalLine:`قِس أين تنكسر طاولتك أنت، وقارن ذلك بورقة البيانات.`,goalCheck:[`تعرف أعلى ساعة SPI بلا أخطاء، وزمن رد بطاقتك، ونسبة نجاح القراءة والبطاقة ثابتة.`,`لُصقت جداولك في لوحة التجارب (Experiments) أعلاه، بجانب المثال.`],learn:[`المقاس مقابل ورقة البيانات`,`سلامة إشارة SPI`,`المهلات وزمن الرد`,`IRQ مقابل الاستطلاع`,`تفريغ العمل إلى عتاد آخر`,`إحصاءات الموثوقية`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت الخاص بالمختبر R6: كل ما في R5، إضافةً إلى عرض الحدود (edge) والتجارب السبع. يسرد <code>help</code> أوامر هذا المختبر بالضبط.`,see:`<code>rfid-lab-r6: reader task started</code>، ثم قائمة أوامر هذا المختبر وعروضه.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`FIFO loopback من 1 إلى 40 MHz، ثم إعادة ضبط الشريحة. نحو 1 s.`,see:`جدول بنسبة % الخطأ لكل MHz ومخطط أعمدة؛ عمود 10 MHz مؤطَّر (حد ورقة البيانات).`,fix:``},2:{does:`300 مجموع اختباري تحسبها الشريحة وESP32.`,see:`صفر اختلافات؛ والشريحة أبطأ بكثير (رحلات SPI ذهابًا وإيابًا).`,fix:``},3:{does:`30 أمر WUPA بالاستطلاع، و30 أخرى بالنوم على سلك IRQ. شغّله والبطاقة موجودة، ثم غائبة.`,see:`عدد وصولات SPI لكل أمر في كل حالة؛ تتسع الفجوة كثيرًا بلا بطاقة.`,fix:`“IRQ never fired”: سلك IRQ (13) مرتخٍ.`},4:{does:`يقلّص مؤقّت انتظار الشريحة من 25 ms إلى 40 µs. نحو 5 s.`,see:`100 % نزولًا إلى ~100 µs، ثم 0 %: هذا زمن رد البطاقة.`,fix:`كلها 0 %: لم تكن البطاقة على القارئ.`},5:{does:`40 دورة كاملة، يُقاس زمن كل خطوة.`,see:`الأدنى / المتوسط / الأقصى بوحدة µs للأوامر WUPA وSELECT وAUTH وREAD.`,fix:`“no complete cycle”: أبقِ البطاقة ثابتة.`},6:{does:`30 محاولة عند كل درجة كسب، عند ارتفاع واحد. شغّله قريبًا، ثم عند ~3 cm.`,see:`% الوجود لكل كسب: كلها 100 عن قرب؛ وتفشل الكسوب المنخفضة أولًا كلما ابتعدت.`,fix:``},7:{does:`500 دورة قراءة كاملة (~10 s). ارفع البطاقة أو أمِلها ببطء أثناء التشغيل.`,see:`أعداد كل نتيجة: ok وabsent وCRC وprotocol… وعدد القراءات في الثانية.`,fix:``}},panels:{0:{title:`التجارب`,intro:`تبويب لكل تجربة: ما الذي تدفعه، وما الذي تبحث عنه، والنتيجة المثالية، وصندوق لجدولك أنت.`},1:{title:`ما تعرضه الشاشة`,intro:`لشاشة اللوحة ستة عروض. النقرة على الزر (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفّذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف استطلاع البطاقات مؤقتًا. اختر عرضًا لترى معنى كل جزء؛ الأرقام تطابق القائمة تحته.`}},steps:[`ارفع <code>rfid-lab-r6</code> إلى اللوحة بالأمر أعلاه (التوصيل نفسه كما في R1). يعرض <code>help</code> أوامر هذا المختبر.`,`البطاقة على القارئ وثابتة (يفيد وضع كتاب فوقها). انتقل إلى عرض <b>الحدود (edge)</b>: النقر المزدوج هناك يشغّل التجربة التالية.`,`<code>edge spi</code> و<code>edge crc</code> و<code>edge irq</code> (والبطاقة موجودة، ثم غائبة).`,`<code>edge timeout</code> و<code>edge timing</code> والبطاقة ثابتة. <b>نقطة التحقق:</b> زمن رد بطاقتك.`,`<code>edge gain</code> عن قرب، ثم عند نحو 3 cm.`,`<code>edge stress 500</code> أثناء رفع البطاقة ببطء.`,`الصق كل جدول في التبويب المطابق أعلاه.`],note:`النقر المزدوج في عرض الحدود يشغّل التجربة التالية. يعيد edge spi ضبط الشريحة بعد انتهائه، تحسبًا لأن تكون كتابة سريعة مشوّهة قد غيّرت إعدادًا. اسحب سلك IRQ وشغّل edge irq: سيلاحظ البرنامج الثابت ويعود إلى الاستطلاع.`},R7:JSON.parse(`{"title":"مدير البطاقات","heading":"أدِر بطاقاتك من تطبيق React","goal":"برنامجه الثابت الخاص (rfid-lab-r7) يحوّل طاولتك إلى باب تديره من تطبيق React صغير (esp-labs/apps/door-app) عبر شبكة Wi-Fi. تحتفظ اللوحة بقائمة البطاقات في ذاكرتها الفلاشية وتقرر كل نقرة بنفسها؛ ولا تحمل البطاقة سوى UID. من التطبيق تضيف البطاقات، وتسمّيها، وتمنحها دورًا، وتحظرها، وتقيّدها بساعات أو بتاريخ انتهاء أو بعدد مرات استخدام، وتنسخ قواعد بطاقة إلى أخرى، وتستبدل بطاقة مفقودة، وتكتب عليها ملصق اسم، وتمسح البيانات التي كتبتها المختبرات، وتحفظ بيانات بطاقة وتعيد كتابتها أو تنسخها إلى بطاقة أخرى، وتفتح الباب عن بُعد، وتفعّل الإغلاق الكامل، وتراقب كل نقرة مباشرةً. قفلان محاكيان (الشاشة وLED): الباب الأمامي لكل الأدوار، وغرفة المدير لبطاقات المدير فقط؛ والقارئ الوحيد مركّب عند أحدهما في كل مرة.","goalLine":"شغّل وسميك كنظام وصول صغير: مقيم واحد وضيف واحد، وشاهد كل قاعدة تحسم نقرة.","goalCheck":["يعرض التطبيق <b>live</b> وكلا الوسمين في القائمة: البطاقة البيضاء كمقيم، وسلسلة المفاتيح كضيف.","عند تمرير البطاقة البيضاء تعرض الشاشة OPEN وكذلك التطبيق؛ وبعد <b>Block</b> تعرض النقرة نفسها DENIED · blocked.","ينخفض عدد استخدامات وسم الضيف مع كل نقرة؛ وعند 0 يُرفض بالرسالة “no uses left”.","تظهر كل نقرة وكل تغيير في سجل الوصول، وفي عرض السجل على اللوحة وفي التطبيق.","تُحفظ بيانات البطاقة البيضاء وتُنسخ إلى سلسلة المفاتيح وتُقارَن: البيانات نفسها، وتبقى سلسلة المفاتيح تفتح باسم <b>Key tag</b>، لأن النسخ لا ينقل UID أبدًا."],"learn":["REST API + WebSocket","قرارات في جهة الخادم","ترتيب القواعد","الفشل مغلقًا (fail closed)","التخزين في NVS","رمز المدير عبر وكيل التطوير","React + zod","نسخ احتياطي، واستعادة، وتحقق","النسخة ليست استنساخًا"],"pins":{"0":{"role":"VCC"},"1":{"role":"RC 3.3V"},"2":{"role":"BLK"},"3":{"role":"RES"},"4":{"role":"DC"},"5":{"role":"CS"},"6":{"role":"SDA"},"7":{"role":"SCL"},"8":{"role":"GND"},"9":{"role":"RC SDA"},"10":{"role":"RC SCK"},"11":{"role":"MOSI"},"12":{"role":"MISO"},"13":{"role":"RC RST"},"14":{"role":"IRQ"},"15":{"role":"RC GND"},"16":{"role":"BTN"},"17":{"role":"BOOT"}},"commands":{"0":{"does":"يرفع البرنامج الثابت للباب. ينسخ أول بناء مكتبات الويب التي يستخدمها W2 أصلًا (ESPAsyncWebServer وAsyncTCP وArduinoJson) إلى esp-labs/.pio.","see":"تعرض الشاشة <b>DOOR door</b>، وLOCKED، و“0 cards in the list”، و<code>http://bench.local</code> في الأسفل بعد الاتصال بشبكة Wi-Fi.","fix":"“no Wi-Fi saved: run W1 once”: يستخدم R7 الشبكة التي حفظها W1/W2. ارفع W1، ونفّذ <code>join</code>، ثم ارفع R7 مرة أخرى."},"1":{"does":"يطبع رمز المدير (المشترك مع W2). كل تغيير في التطبيق يحتاج إليه.","see":"<code>Admin token: 3f…</code> وأين تضعه.","fix":"أبقِه خارج المحادثات وgit. يستبدله <code>token new</code>."},"2":{"does":"ينشئ ملف إعدادات التطبيق: <code>BENCH_URL=http://bench.local</code> (أو عنوان IP من <code>status</code>) و<code>BENCH_TOKEN=</code> الرمز.","see":"ملف .env بجانب package.json. وهو مستثنى من git.","fix":""},"3":{"does":"يثبّت التطبيق (React 19 وVite 8 وzod: الإصدارات نفسها كما في لوحة المعلومات) ويشغّله. يمرّر Vite المسارين /api و/ws إلى اللوحة ويضيف الرمز في الطريق، فلا يحمله المتصفح أبدًا.","see":"افتح <code>http://localhost:5174</code>: تعرض لوحة الباب <b>live</b>، وتعرض الشريحة B2h · FM17522 (شريحتك المقلّدة)، وتعرض الساعة الوقت.","fix":"“connecting…” إلى ما لا نهاية: هل اللوحة على Wi-Fi (تذييل الشاشة)؟ هل يُفتح <code>http://bench.local/api</code> في المتصفح؟ FRITZ!Box: اسمح لأجهزة Wi-Fi بالتخاطب فيما بينها (W2)."},"4":{"does":"تنتظر اللوحة 20 s بطاقة لم ترها من قبل؛ تعرض الشاشة ADD A CARD ويومض LED بالأزرق. ثم ضع البطاقة البيضاء على القارئ.","see":"إشعار “White card added”، والبطاقة في القائمة مع <b>opens now</b>، وسطر “enrolled” في السجل.","fix":"“already in the list”: هذه البطاقة مسجّلة؛ مرّر بطاقة أخرى أو احذفها أولًا."},"5":{"does":"الأمر نفسه لسلسلة المفاتيح. يبدأ الضيوف بـ 5 استخدامات.","see":"Key tag · guest · <b>5 uses left</b>.","fix":""},"6":{"does":"تقرر اللوحة من قائمتها: OPEN لمدة 5 s (LED أخضر، ويُفتح القفل) أو DENIED لمدة 2 s (LED أحمر، مع السبب).","see":"تتحدّث لوحة الباب في التطبيق والسجل خلال ثانية؛ وتنزل استخدامات الضيف 5 ← 4 ← 3.","fix":"لا شيء يحدث، أو “card can't be read”: انظر إلى خلية <b>Reader chip</b> في التطبيق والشريط تحتها. تعني “settings restored” أن RC522 أعاد ضبط نفسه عندما انخفض جهده 3.3 V (غالبًا أثناء إرسال Wi-Fi): استخدم أسلاكًا قصيرة إلى طرف 3.3V، وأطراف مشبك مضغوطة أو ملحومة. “IRQ wire stays quiet” غير ضارة: تستطلع اللوحة بدلًا من ذلك. في المراقب التسلسلي: يطبع <code>status</code> الشيء نفسه."},"7":{"does":"أسرع قاعدة: تُرفض البطاقة المحظورة قبل فحص أي شيء آخر.","see":"<b>blocked</b> على البطاقة؛ ونقرتها التالية تعرض DENIED · blocked.","fix":""},"8":{"does":"Office hours (08-18)، وNight shift (22-06، عبر منتصف الليل)، وWeekend guest (10 استخدامات حتى الأحد 20:00)، وOne visit (استخدام واحد، 24 h)، وLost card (محظورة). يرسل الحفظ ما تغيّر فقط.","see":"يتغير سطر قاعدة البطاقة وشارة “opens now” فورًا.","fix":"“no clock yet”: تُرفض البطاقات المقيّدة بتاريخ أو وقت حتى تحصل اللوحة على وقت الإنترنت (الفشل مغلقًا)."},"9":{"does":"دور رابع: بطاقات المدير تفتح الباب الأمامي كالمقيم، وهي البطاقات الوحيدة التي تفتح غرفة المدير. وتفتح أيضًا أثناء الإغلاق الكامل.","see":"يعرض صف البطاقة <b>front door ✓</b> و<b>admin room ✓</b>؛ ويعرض صف المقيم <b>admin room · admins only</b>.","fix":""},"10":{"does":"للطاولة قارئ واحد، فيُركَّب عند قفل واحد في كل مرة (يُحفظ على اللوحة). في المراقب التسلسلي: <code>at admin</code> و<code>at front</code>.","see":"تحصل بلاطة غرفة المدير على الإطار الأخضر المزرق و“reader here”؛ وتعرض الشاشة ADMIN ROOM فوق القفل.","fix":""},"11":{"does":"اللوحة نفسها، والقائمة نفسها، لكن القفل مختلف: يأتي فحص الدور مباشرة بعد “blocked”، قبل أي ساعات أو تواريخ.","see":"بطاقة المدير: غرفة المدير OPEN لمدة 5 s. بطاقة المقيم: DENIED · <b>admins only</b>، ويُسجَّل مع “admin room”. أعد القارئ إلى مكانه: يفتح المقيم الباب الأمامي من جديد.","fix":"ما زال المقيم يفتح؟ تحقق من البلاطة التي تعرض “reader here”."},"12":{"does":"يفتح قفلًا واحدًا من التطبيق أو المراقب التسلسلي، أيًّا كانت البطاقة القريبة؛ و<code>open</code> وحده يعني الباب الأمامي.","see":"تصبح تلك البلاطة خضراء لمدة 5 s؛ ويعرض السجل “opened from the app” مع القفل.","fix":""},"13":{"does":"لا تفتح إلا بطاقات الصيانة والمدير. يتوهج LED بالعنبري أثناء الخمول.","see":"تعرض الشاشة LOCKDOWN، وكل نقرة مقيم أو ضيف تعطي DENIED · lockdown.","fix":""},"14":{"does":"يكتب الاسم في الكتلة 4 والدور في الكتلة 5 من تلك البطاقة (بمفتاح المصنع، القطاع 1 فقط)، ثم يقرؤهما مرة أخرى.","see":"“label written”. اقرأ البطاقة على القارئ: تعرض الكتلة 4 اسمها.","fix":"ما زال الباب يتجاهل الملصق: فهو يقرر من قائمته الخاصة. اكتب أي اسم هناك ولن يتغير شيء."},"15":{"does":"نقرة ثانية للتأكيد. تعود الكتل 4-6 و8-10 إلى أصفار حيث تسمح بتات الوصول (الملصق، ورصيد R5). لا تُمسّ المفاتيح ولا المقاطع الختامية ولا الكتلة 0 أبدًا.","see":"“6 of 6 data blocks cleared”.","fix":""},"16":{"does":"نقرة ثانية للتأكيد. تنسى اللوحة البطاقة؛ أما البطاقة نفسها فلا تُمسّ.","see":"نقرتها التالية: DENIED · unknown card.","fix":""},"17":{"does":"يملأ النموذج بدور بطاقة أخرى وساعاتها وتاريخ انتهائها واستخداماتها (دون اسمها ولا حظرها). يرسل الحفظ ما تغيّر.","see":"صار للبطاقتين الآن سطر القاعدة نفسه.","fix":""},"18":{"does":"يقرأ الكتل 4-6 و8-10 بمفتاح المصنع ويحتفظ بها على اللوحة كلقطة مسمّاة (حتى 8، في NVS). في المراقب التسلسلي: <code>save White</code> و<code>saved</code>.","see":"“6 of 6 blocks saved as …” ولقطة بخلاياها الست: نص، وقيم (رصيد R5)، وأصفار.","fix":"“no lab block opens”: القطاعان 1-2 في تلك البطاقة يستخدمان مفتاحًا آخر: لا شيء يُحفظ."},"19":{"does":"ينزّل اللقطة كملف JSON على جهاز Mac؛ ويعيد Import مثل هذا الملف إلى اللوحة (كتل المختبر فقط، ويُتحقق منه مرتين: من التطبيق ومن اللوحة).","see":"ملف <code>card-data-….json</code>؛ وبعد الاستيراد، لقطة “from a file”.","fix":""},"20":{"does":"يقرأ البطاقة على القارئ، ثم تعرض الشاشة COPY: 2ND CARD ويومض LED بالبنفسجي. ارفعها وضع البطاقة الأخرى خلال 20 s: تُكتب كل كتلة وتُقرأ مرة أخرى. في المراقب التسلسلي: <code>copy</code> و<code>cancel</code>.","see":"“6 of 6 blocks copied from White card onto 9C4F6A0D”، وسطر “data copied here” في السجل.","fix":"وضع البطاقة نفسها مرة أخرى لا يفعل شيئًا (تنتظر بطاقة مختلفة). والإلغاء لا يكتب شيئًا."},"21":{"does":"يقرأ البطاقة على القارئ ويقابلها بلقطة، كتلة بكتلة.","see":"<b>same</b> لكل كتلة منسوخة. مرّر الآن سلسلة المفاتيح: ما زالت تفتح باسم <b>Key tag</b>.","fix":""},"22":{"does":"نقرة ثانية للتأكيد. لقطة تعود إلى البطاقة التي أُخذت منها (restore)، مثلًا بعد أن أنفق R5 رصيدها، أو إلى بطاقة أخرى. في المراقب التسلسلي: <code>restore 1</code>.","see":"“… written to 9C4F2A1B (the card it came from)”.","fix":""},"23":{"does":"لبطاقة مفقودة أو معطوبة: البطاقة الجديدة التالية التي تمررها ترث اسمها ودورها وقواعدها؛ وتبقى القديمة في القائمة محظورة ومعاد تسميتها “… old”.","see":"مدخلان: تفتح البطاقة الجديدة، وتعرض القديمة DENIED · blocked إن ظهرت يومًا.","fix":""}},"panels":{"0":{"title":"أي قاعدة تحسم؟","intro":"تفحص اللوحة القواعد بهذا الترتيب، وتفوز أول قاعدة تقول لا. أعدّ بطاقة، والساعة، والإغلاق الكامل، وانظر أي قاعدة تحسم. هو الترتيب نفسه في kit/lib/door-rules/src/access_rules.h (مُختبَر على Mac)."},"1":{"title":"تابع نقرة واحدة، وكتلة واحدة، وبطاقة جديدة واحدة، ونسخة واحدة","intro":"ما الذي يعبر الأسلاك وWi-Fi: التطبيق لا يتحدث مع القارئ مباشرة، والبطاقة لا تقرر أي شيء."},"2":{"title":"ما الذي تنقله النسخة","intro":"احفظ بيانات البطاقة البيضاء، وانسخها إلى سلسلة المفاتيح، وراقب أي الكتل تتحرك. الكتلة 0 (UID) والمقاطع الختامية (المفاتيح وبتات الوصول) لا تتحرك أبدًا، والقطاع الذي لا يُفتح بمفتاح المصنع يُتخطى ولا يُجبَر."}},"steps":["التوصيل نفسه كما في R1. ارفع <code>rfid-lab-r7</code> إلى اللوحة. تحتاج اللوحة إلى شبكة Wi-Fi التي حفظها W1/W2.","في المراقب: <code>token</code>. انسخه إلى <code>esp-labs/apps/door-app/.env</code> بصيغة <code>BENCH_TOKEN=</code>.","نفّذ <code>pnpm install</code> و<code>pnpm dev</code> في esp-labs/apps/door-app، وافتح <code>http://localhost:5174</code>. <b>نقطة التحقق:</b> live، والشريحة B2h، وساعة.","أضف البطاقة البيضاء كمقيم وسلسلة المفاتيح كضيف. <b>نقطة التحقق:</b> كلتاهما في القائمة، و“opens now”.","مرّر الاثنتين عدة مرات: OPEN، وانخفاض استخدامات الضيف، وكل نقرة في السجل.","احظر البطاقة البيضاء ومرّرها (DENIED · blocked)، ثم ارفع الحظر. جرّب القوالب الجاهزة والإغلاق الكامل، وراقب لوحة “Which rule decides?” وهي توافق.","اكتب ملصقًا على بطاقة، واقرأه مرة أخرى، ثم امسحه. ثم أزل سلسلة المفاتيح من القائمة ومرّرها: unknown card.","احفظ بيانات البطاقة البيضاء، وانسخها إلى سلسلة المفاتيح، وقارن. <b>نقطة التحقق:</b> البيانات نفسها على الاثنتين، ومع ذلك تفتح كل بطاقة باسمها.","نزّل اللقطة، وامسح البطاقة البيضاء، واكتب اللقطة مرة أخرى، وقارن: استُعيدت."],"note":"لماذا تقرر اللوحة لا البطاقة: يستطيع أي شخص يملك قارئًا قراءة UID بطاقة MIFARE Classic وبياناتها، فهي تصلح كبطاقة اسم لا كدليل. تُبقي أنظمة الوصول الحقيقية القرار على خادم وتستخدم بطاقات بتشفير حديث (مثل MIFARE DESFire)؛ ويعلّمك هذا المختبر جانب الخادم من ذلك. قراءة API متاحة على شبكة Wi-Fi لديك؛ أما كل تغيير فيحتاج إلى الرمز. تعيش قائمة البطاقات في NVS على اللوحة وتنجو من إعادة رفع البرنامج؛ وهي منفصلة عن المختبرات R1-R6. النسخ ينقل البيانات فقط: الكتلة 0 تُكتب مرة واحدة في المصنع، فتحتفظ النسخة بـ UID الخاص بها ويعاملها الباب كبطاقة مختلفة. ولهذا أيضًا لا يعتمد الوصول على البيانات أبدًا: لأنها كانت ستُنسخ معها."}`),R8:{title:`أصدقاء البطاقات`,heading:`يعيش صديق في كل بطاقة`,goal:`مختبر للأطفال، مبني من أجزاء R7. برنامجه الثابت الخاص (rfid-lab-r8) يجعل كل بطاقة بيتًا لصديق: ثعلب، أو روبوت، أو تنين، أو بطريق، أو كائن فضائي، أو قط، أو ضفدع، أو حصان وحيد القرن. مرّر بطاقة فيقفز صديقها على شاشة اللوحة مع نجوم بألوانه، وبالثلاثي الأبعاد في تطبيق React صغير (esp-labs/apps/friends-app)، بحركته وبريقه وسمائه ولحنه. تعرض البطاقة 1 والبطاقة 2 صديقين مختلفين؛ ومرّرهما معًا فيلعبان معًا. تضيف البطاقة الجديدة نفسها عند أول نقرة، وتسحب صديقًا إليها. للتطبيق تبويبان: Play للأطفال، وSetup للكبار (لوحة حقيقية أو وهمية، وحالة القارئ، وقائمة البطاقات، والصوت، والحركة الهادئة، والنهار أو الليل).`,goalLine:`امنح البطاقة البيضاء وسلسلة المفاتيح صديقًا لكل منهما، ثم مرّرهما وشاهد الصديقين يلعبان.`,goalCheck:[`يعرض تبويب Setup في التطبيق <b>live</b>، وشريحة القارئ B2h، وعدد البطاقات يزداد كلما مررت بطاقات جديدة.`,`تعرض البطاقة الجديدة علامة <b>?</b> مترنحة على الشاشة و“New card! Who lives here?” في التطبيق.`,`بعد سحب صديق إليها، يقفز الصديق على الشاشة وبالثلاثي الأبعاد في اللحظة نفسها.`,`تمرير البطاقة 1 ثم البطاقة 2 يضع صديقين مختلفين على المسرح ثلاثي الأبعاد، كل منهما على بطاقته المرقّمة.`,`النقر على صديق في المسرح ثلاثي الأبعاد يجعله يؤدي حركته مرة أخرى.`],learn:[`UID كمفتاح`,`التسجيل التلقائي`,`الحالة على اللوحة، والعرض في التطبيق`,`الدفع عبر WebSocket`,`السحب والإفلات بأحداث المؤشر`,`تظليل كرتوني بـ three.js`,`Web Audio`,`بدائل ميسّرة (النقر، ولوحة المفاتيح)`],pins:{0:{role:`VCC`},1:{role:`RC 3.3V`},2:{role:`BLK`},3:{role:`RES`},4:{role:`DC`},5:{role:`CS`},6:{role:`SDA`},7:{role:`SCL`},8:{role:`GND`},9:{role:`RC SDA`},10:{role:`RC SCK`},11:{role:`MOSI`},12:{role:`MISO`},13:{role:`RC RST`},14:{role:`IRQ`},15:{role:`RC GND`},16:{role:`BTN`},17:{role:`BOOT`}},commands:{0:{does:`يرفع البرنامج الثابت للأصدقاء. يستخدم مكتبات الويب الخاصة بـ R7 وشبكة Wi-Fi التي حفظها W1/W2.`,see:`<b>FRIENDS stage</b>، ومخطط بطاقة يتنفس و“Tap a card!”، و<code>http://bench.local</code> في الأسفل بعد الاتصال بشبكة Wi-Fi.`,fix:`“no Wi-Fi saved: run W1 once”: ارفع W1، ونفّذ <code>join</code>، ثم R8 مرة أخرى.`},1:{does:`يطبع رمز المدير (نفسه الذي يستخدمه W2 وR7). نقل صديق إلى بطاقة يحتاج إليه.`,see:`<code>Admin token: 3f…</code>`,fix:`أبقِه خارج المحادثات وgit.`},2:{does:`<code>BENCH_URL=http://bench.local</code> (أو عنوان IP من <code>status</code>)، و<code>BENCH_TOKEN=</code> الرمز.`,see:`ملف .env مستثنى من git بجانب package.json.`,fix:``},3:{does:`يشغّل التطبيق على المنفذ 5175 (يمكن تشغيله بجانب door-app). يمرّر Vite المسارين /api و/ws إلى اللوحة ويضيف الرمز. يستطيع جهاز لوحي على شبكة Wi-Fi نفسها فتحه على عنوان Mac.`,see:`<code>http://localhost:5175</code>: تبويبا Play وSetup، و“board live” في الأعلى.`,fix:`لا توجد لوحة في متناولك؟ Setup ← <b>Pretend board</b> يعمل بالقواعد نفسها في المتصفح.`},4:{does:`تضيفها اللوحة كبطاقة تالية (حتى 12) دون أحد عليها.`,see:`الشاشة: بطاقة ? مترنحة، و“New card! Give it a friend”. التطبيق: بلاطة جديدة تطلب صديقًا.`,fix:`“12 cards!”: انسِ واحدة من Setup، أو نفّذ في المراقب التسلسلي <code>forget 3</code>.`},5:{does:`أو انقر على الصديق ثم على البطاقة (أو Enter، Enter بلوحة المفاتيح). يرسل <code>PUT /api/card?uid=… {"character":"robot"}</code>، ثم يعرضه. في المراقب التسلسلي: <code>give 2 robot</code>.`,see:`يقفز الصديق على الشاشة وعلى المسرح ثلاثي الأبعاد؛ وتعرض البلاطة وجهه.`,fix:`401: BENCH_TOKEN مفقود أو قديم، أعد تشغيل <code>pnpm dev</code> بعد تغيير .env.`},6:{does:`عند كل نقرة: حركة الصديق، وبريقه، وسماؤه، ولحنه. تلعب بطاقتان معًا إن مُررتا خلال 30 s؛ وثلاث على الأكثر.`,see:`صديقان على المسرح، كل منهما واقف على بطاقته المرقّمة.`,fix:`لا صوت: المس الصفحة مرة واحدة (تحتاج المتصفحات إلى ذلك)، أو افحص Setup ← Sound.`},7:{does:`اسم لذلك الصديق على تلك البطاقة (حتى 15 حرفًا عاديًا). في المراقب التسلسلي: <code>name 1 Rusty</code>، و<code>name 1 -</code> للعودة.`,see:`“Hi again! Rusty” على الشاشة وفي الفقاعة.`,fix:``},8:{does:`يسرد كل بطاقة مع صديقها وزياراتها، والأصدقاء الذين يعرفهم هذا البرنامج الثابت.`,see:`<code>1  9C4F2A1B  fox  Foxy  taps 5</code>`,fix:``}},panels:{0:{title:`تعرّف على الشخصيات`,intro:`الأصدقاء الثمانية، مرسومون كما ترسمهم اللوحة (دوائر ومثلثات، بلا صور في الذاكرة الفلاشية). اضغط على أحدهم لترى ماذا يفعل. تخزّن اللوحة معرّفه فقط؛ ويعرف التطبيق حركته وبريقه وسماءه ولحنه.`},1:{title:`تابع نقرة واحدة، وبطاقة جديدة تحصل على صديق`,intro:`لا تحمل البطاقة سوى UID. تقرر اللوحة من يسكنها، وتعرضه على شاشتها، وتخبر كل تطبيق.`}},steps:[`التوصيل نفسه كما في R1. ارفع <code>rfid-lab-r8</code> إلى اللوحة. تحتاج اللوحة إلى شبكة Wi-Fi التي حفظها W1/W2.`,`في المراقب: <code>token</code>، إلى <code>esp-labs/apps/friends-app/.env</code> بصيغة <code>BENCH_TOKEN=</code>.`,`نفّذ <code>pnpm install</code> و<code>pnpm dev</code> في esp-labs/apps/friends-app، وافتح <code>http://localhost:5175</code>. <b>نقطة التحقق:</b> يقول Setup إنه live، والشريحة B2h.`,`مرّر البطاقة البيضاء وسلسلة المفاتيح مرة لكل منهما. <b>نقطة التحقق:</b> بلاطتان في Play، تسأل كل منهما “Who lives here?”.`,`اسحب صديقًا إلى كل بطاقة. راقب شاشة اللوحة والمسرح ثلاثي الأبعاد معًا.`,`مرّر البطاقة 1 ثم البطاقة 2: صديقان مختلفان يلعبان معًا. انقر على أحدهما في المسرح.`,`جرّب Setup ← Calm motion وNight، ثم سلّم الجهاز اللوحي إلى طفل.`],note:`الصديق ليس على البطاقة: تحتفظ اللوحة بقائمة (UID ← معرّف الصديق) في NVS، ضمن المساحة friends، منفصلة عن قائمة الباب في R7. لذلك تصلح أي بطاقة، حتى التي لا تستطيع الكتابة عليها، ونقل الصديق فوري. الفكرة نفسها كما في R7 (لا تحمل البطاقة سوى UID) في ثوب أكثر ودًّا. تُبنى المجسمات ثلاثية الأبعاد في الشيفرة من كرات ومخروطات ومربعات بتظليل كرتوني، فلا ملفات نماذج، وترسم شاشة اللوحة الأشكال نفسها بالثنائي الأبعاد.`}};export{e as default};
